    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
while True:
    # Choose three distinct positive integers >= 2.
    x = rng.randint(2, 5)
    y = rng.randint(x + 1, x + 5)
    z = rng.randint(y + 1, y + 5)

    # Avoid roots being in an arithmetic progression, which might be easier to guess
    if y - x == z - y:
        continue

    e1 = x + y + z
    e2 = x*y + y*z + z*x
    e3 = x*y*z

    A = e1 + e2 + e3
    B = e1 * e2
    D = x**3 + y**3 + z**3

    answer = x**2 + y**2 + z**2

    # Ensure numbers are large enough to be non-trivial
    if B < 500 or D < 200 or A < 100:
        continue

    # The quartic for e1 has a unique positive root by construction,
    # as t^3 + e1*t^2 + (e1^2-3)t + 3*e2 is always positive for t>0
    # when x,y,z >= 2.
    # e1 >= 2+3+4=9, so e1^2-3 > 0.

    return {
        "A": A,
        "B": B,
        "D": D,
        "answer": answer
    }

    def verifier(assign):
A = assign["A"]
B = assign["B"]
D = assign["D"]
answer = assign["answer"]

def get_divisors(n):
    n = abs(n)
    if n == 0: return []
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return list(divs)

def find_int_roots(coeffs):
    const_term = 0
    for c in reversed(coeffs):
        if c != 0:
            const_term = c
            break
    if const_term == 0:
        # This case is not expected for our polynomials.
        return []

    roots = []
    divisors = get_divisors(const_term)

    for d in divisors:
        for r in [d, -d]:
            if r in roots: continue
            val = 0
            for coeff in coeffs:
                val = val * r + coeff
            if val == 0:
                roots.append(r)
    return sorted(roots)

# The system in terms of e1, e2, e3 leads to a quartic for e1:
# t^4 - 3t^2 + (3A - D - 3B)t - 3B = 0
coeff_t1 = 3*A - D - 3*B
quartic_coeffs = [1, 0, -3, coeff_t1, -3*B]

all_roots_e1 = find_int_roots(quartic_coeffs)
pos_roots_e1 = [r for r in all_roots_e1 if r > 0]

if len(pos_roots_e1) != 1:
    # The problem must have a unique valid e1.
    return False, None

e1 = pos_roots_e1[0]

if B % e1 != 0:
    # e2 must be an integer.
    return False, None
e2 = B // e1

e3 = A - e1 - e2

# Verify that these values satisfy the third original equation
if e1**3 - 3*e1*e2 + 3*e3 != D:
    return False, None

# The integers x,y,z are roots of P(t) = t^3 - e1*t^2 + e2*t - e3 = 0.
cubic_coeffs = [1, -e1, e2, -e3]
roots = find_int_roots(cubic_coeffs)

pos_roots_xyz = [r for r in roots if r > 0]

# Check if we found three distinct positive integer roots.
if sum(pos_roots_xyz) != e1 or len(pos_roots_xyz) != 3:
    return False, None

if len(set(pos_roots_xyz)) != 3:
    # Roots must be distinct.
    return False, None

# Difficulty check: integers should be >= 2.
if any(r < 2 for r in pos_roots_xyz):
    return False, None

# The question asks for x^2+y^2+z^2, which is p2 = e1^2 - 2*e2.
calculated_answer = e1**2 - 2*e2

return calculated_answer == answer, calculated_answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
